mapper.select:
select u.id,u.username,u.status,u.create_time,u.update_time,u.deleted, up.nickname,up.avatar,up.phone,up.email,up.gender,up.birthday from user u left join user_profile up on u.id = up.user_id
and u.role = 1
and u.deleted = #{dto.deleted}
and up.nickname like concat('%',#{dto.keyword},'%')
and u.status = #{dto.status}
and up.gender = #{dto.gender}
order by u.create_time desc
